{
  "name": "@cend/octopus-plugin-workbuddy-auth",
  "version": "1.3.0",
  "description": "Multi-account WorkBuddy / WorkBuddy AI plugin for Octopus with manual check-in and credit query. Requires Octopus >=0.1.9 with plugin API v1 (managed-providers + page-rpc).",
  "type": "module",
  "main": "./opencode.mjs",
  "exports": {
    ".": "./opencode2.mjs"
  },
  "files": [
    "index.mjs",
    "opencode.mjs",
    "opencode2.mjs",
    "ui",
    "README.md",
    "LICENSE",
    "NOTICE",
    "octopus.mjs",
    "account-store.mjs",
    "accounts.mjs",
    "OCTOPUS.md"
  ],
  "keywords": [
    "octopus",
    "octopus-plugin",
    "opencode",
    "workbuddy",
    "codebuddy"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public",
    "tag": "latest",
    "registry": "https://registry.npmjs.org"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/CE-ND/Octopus-plugin.git",
    "directory": "plugins/octopus-plugin-workbuddy-auth"
  },
  "octopus": {
    "displayName": "WorkBuddy",
    "apiVersion": 1,
    "requires": ["managed-providers", "page-rpc"],
    "compatibilityNotice": "需要 Octopus v0.1.9 或更高版本，并支持插件 API v1（managed-providers、page-rpc）；旧版宿主请先升级。Requires Octopus >=0.1.9 with plugin API v1 support.",
    "replaces": [
      "@octopus/plugin-workbuddy-auth",
      "@magpie-community/opencode-workbuddy-auth"
    ],
    "upstream": {
      "name": "@magpie-community/opencode-workbuddy-auth",
      "version": "0.2.20"
    },
    "ui": {
      "pages": [
        {
          "id": "manage",
          "title": "WorkBuddy 管理",
          "entry": "ui/manage.html",
          "slot": "manage"
        }
      ]
    },
    "entry": "./octopus.mjs"
  },
  "scripts": {
    "test": "node --test tests/accounts.test.mjs"
  }
}
